import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const CLIENT_SOURCE_FILES = ["styles.js", "core.js", "shadow.js", "switch-button.js", "main.js"];
export const PLUGIN_ID = "dsh-tavern-page-switch";

const HEADER = [
  "// Generated by build.mjs; edit src/client/*.js and rebuild.",
  "window.__ModuleLoader__.load({",
  '  id: "dsh-tavern-page-switch",',
  '  inject: ["slots"],',
  "  factory: (require) => {",
  "    const module = { exports: {} };",
  "    const exports = module.exports;",
  "    let React = null;",
  "    try {",
  '      React = require("react");',
  "    } catch (error) {",
  '      console.warn("[dsh-tavern-page-switch] React is unavailable; plugin disabled", error);',
  '      exports.name = "dsh-tavern-page-switch";',
  "      exports.inject = [];",
  "      exports.apply = function () {};",
  "      return module.exports;",
  "    }",
  "    const h = React.createElement;",
  "",
].join("\n");

const FOOTER = ["", "    return module.exports;", "  },", "});", ""].join("\n");

const root = path.dirname(fileURLToPath(import.meta.url));
const outputPath = path.join(root, "lib", "client.js");

export async function buildClientSource() {
  const chunks = [HEADER];
  for (const name of CLIENT_SOURCE_FILES) {
    const source = await readFile(path.join(root, "src", "client", name), "utf8");
    chunks.push("// ---- src/client/" + name + " ----");
    chunks.push(source.replace(/\s+$/, ""));
    chunks.push("");
  }
  chunks.push(FOOTER);
  return chunks.join("\n");
}

export async function build({ check = false } = {}) {
  const output = await buildClientSource();
  let previous = null;
  try {
    previous = await readFile(outputPath, "utf8");
  } catch (error) {
    previous = null;
  }
  if (previous === output) {
    console.log("lib/client.js is up to date");
    return { changed: false };
  }
  if (check) {
    const error = new Error("lib/client.js is stale; run node build.mjs");
    error.code = "STALE_CLIENT";
    throw error;
  }
  await writeFile(outputPath, output);
  console.log("wrote lib/client.js");
  return { changed: true };
}

const entry = process.argv[1] ? path.resolve(process.argv[1]) : "";
if (entry === fileURLToPath(import.meta.url)) {
  try {
    await build({ check: process.argv.includes("--check") });
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
